#!/usr/bin/env node
/**
 * apply-static-chrome.cjs
 *
 * Injects the ONE shared header + footer (scripts/partials/site-chrome.cjs)
 * into the hand-authored static pages under public/ that are NOT generated by
 * another script. Idempotent and marker-based: safe to re-run every build.
 *
 * Generated pages handle their own chrome:
 *   - location pages  -> generate-location-pages.cjs
 *   - brand pages     -> generate-brand-pages.js
 *   - event pages     -> generate-event-pages.js / prerender (React chrome)
 *
 * This script covers the remaining static files: about, faq, privacy, 404.
 * Each entry declares how to strip its legacy chrome and where to drop the
 * shared chrome in. Runs in prebuild before vite copies public/ to dist/.
 */

const fs = require('fs');
const path = require('path');
const {
  SITE_CHROME_CSS,
  SITE_HEADER_HTML,
  SITE_FOOTER_HTML,
  HEADER_START,
  HEADER_END,
  FOOTER_START,
  FOOTER_END,
  CSS_START,
  CSS_END,
} = require('./partials/site-chrome.cjs');

const ROOT = path.resolve(__dirname, '..');

function reEscape(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function between(start, end) {
  return new RegExp(`${reEscape(start)}[\\s\\S]*?${reEscape(end)}`);
}

// Inject scoped chrome CSS just before </head>, idempotent.
function injectCss(html) {
  const re = between(CSS_START, CSS_END);
  if (re.test(html)) return html.replace(re, SITE_CHROME_CSS);
  return html.replace('</head>', `${SITE_CHROME_CSS}\n</head>`);
}

// Replace whatever legacy header markup matches `legacyHeaderRe` with the
// shared header. On re-run, it is marker-based.
function injectHeader(html, legacyHeaderRe) {
  const re = between(HEADER_START, HEADER_END);
  if (re.test(html)) return html.replace(re, SITE_HEADER_HTML);
  if (legacyHeaderRe && legacyHeaderRe.test(html)) {
    return html.replace(legacyHeaderRe, SITE_HEADER_HTML);
  }
  // No legacy header (e.g. 404): drop the shared header right after <body...>.
  return html.replace(/(<body[^>]*>)/, `$1\n${SITE_HEADER_HTML}`);
}

// Footer handling. The shared footer is always placed full-bleed just before
// </body>. If `legacyFooterRe` is given we first strip the nested legacy footer
// so it does not double up. Marker-based and idempotent on re-run.
function injectFooter(html, legacyFooterRe) {
  const re = between(FOOTER_START, FOOTER_END);
  if (re.test(html)) {
    // Already migrated: move/refresh in place.
    return html.replace(re, SITE_FOOTER_HTML);
  }
  let out = html;
  if (legacyFooterRe && legacyFooterRe.test(out)) {
    out = out.replace(legacyFooterRe, '');
  }
  return out.replace('</body>', `${SITE_FOOTER_HTML}\n</body>`);
}

// Page-specific legacy chrome shapes. headerRe / footerRe are matched once on
// first migration; after that the BOOM-GEN markers take over.
const PAGES = [
  {
    file: 'public/about/index.html',
    // <nav> ... </nav> sits inside .container; strip just the nav.
    headerRe: /\s*<nav>\s*<a href="\/" class="logo">[\s\S]*?<\/nav>/,
    // <footer> ... </footer> inside .container.
    footerRe: /\s*<footer>\s*<div class="footer-grid">[\s\S]*?<\/footer>/,
  },
  {
    file: 'public/faq/index.html',
    // nav + breadcrumb bar.
    headerRe: /\s*<!-- Navigation -->\s*<nav class="nav">[\s\S]*?<\/nav>\s*<!-- Breadcrumb -->\s*<div class="breadcrumb">[\s\S]*?<\/div>/,
    footerRe: /\s*<!-- Footer -->\s*<footer>[\s\S]*?<\/footer>/,
  },
  {
    file: 'public/privacy/index.html',
    // Minimal back-link nav only; no footer originally.
    headerRe: /\s*<!-- Navigation -->\s*<nav class="container[^"]*">[\s\S]*?<\/nav>/,
    footerRe: null,
  },
  {
    file: 'public/404.html',
    // No header or footer originally.
    headerRe: null,
    footerRe: null,
  },
];

function apply() {
  let touched = 0;
  for (const page of PAGES) {
    const abs = path.join(ROOT, page.file);
    if (!fs.existsSync(abs)) {
      console.log(`  skip (missing): ${page.file}`);
      continue;
    }
    const before = fs.readFileSync(abs, 'utf8');
    let html = before;
    html = injectCss(html);
    html = injectHeader(html, page.headerRe);
    html = injectFooter(html, page.footerRe);
    if (html !== before) {
      fs.writeFileSync(abs, html, 'utf8');
      touched++;
      console.log(`  chrome applied: ${page.file}`);
    } else {
      console.log(`  unchanged: ${page.file}`);
    }
  }
  console.log(`Static chrome: ${touched} file(s) updated`);
}

apply();
